const d = $json.body ?? $json;
const topic = String(d.topic ?? '').trim();
const source_url = String(d.source_url ?? '').trim();
const format = String(d.format ?? 'article').trim().toLowerCase();
const audience = String(d.audience ?? 'público geral').trim();
const source_text = String(d.source_text ?? '').trim();
if (format === 'news_summary' && !source_text) throw new Error('Para resumo de notícia, source_text da fonte primária é obrigatório.');
if (source_text.length > 25000) throw new Error('source_text excede 25000 caracteres.');
const request_id = String(d.request_id ?? '').trim();
if (!topic || topic.length < 8) throw new Error('Informe uma pauta com pelo menos 8 caracteres.');
if (!/^https:\/\//i.test(source_url)) throw new Error('source_url HTTPS é obrigatório.');
if (!request_id) throw new Error('request_id obrigatório para rastreabilidade.');
if (!['article','news_summary','video_script','social_post'].includes(format)) throw new Error('format inválido.');
const sensitivePattern = /\\bcpf\\b|\\bcnpj\\b|senha|prontu[aá]rio|documento sigiloso|dados pessoais de cliente|caso individual identificável|nome completo de cliente/i;\nif (sensitivePattern.test(topic) || sensitivePattern.test(source_text)) throw new Error('A pauta ou fonte parece conter informação pessoal/sigilosa. Remova dados identificáveis e use fontes públicas.');
return [{json:{topic,source_url,source_text,format,audience,request_id,received_at:new Date().toISOString()}}];

const resp = $json;
let raw = resp.choices?.[0]?.message?.content;
if (typeof raw !== 'string' || !raw.trim()) throw new Error('O provedor de IA não retornou conteúdo no formato esperado.');
raw = raw.trim().replace(/^```json\s*/i,'').replace(/\s*```$/,'');
let draft;
try { draft = JSON.parse(raw); } catch(e) { throw new Error('A resposta da IA não é JSON válido; nada será enviado ao WordPress.'); }
const title = String(draft.title ?? '').trim();
const excerpt = String(draft.excerpt ?? '').trim().slice(0,500);
const rawContent = String(draft.content ?? '').trim();\nconst prior = $node['Validar pauta e fonte'].json;\nconst safeUrl = String(prior.source_url);\nconst trackedContent = rawContent + '\\n\\n<p><strong>Fonte para conferência:</strong> <a href=\"' + safeUrl + '\" rel=\"nofollow noopener noreferrer\">' + safeUrl + '</a></p><p><small>Identificador editorial: ' + String(prior.request_id).replace(/[^a-zA-Z0-9_-]/g,'') + '</small></p>';\nconst content = trackedContent;
if (!title || !content) throw new Error('Título ou conteúdo ausente.');
if (title.length > 180 || content.length > 60000) throw new Error('Conteúdo excede os limites definidos.');
return [{json:{title,excerpt,content,status:'draft',request_id:$node['Validar pauta e fonte'].json.request_id,source_url:$node['Validar pauta e fonte'].json.source_url,format:$node['Validar pauta e fonte'].json.format,created_for_review:true}}];
